#!/usr/bin/env bash
set -euo pipefail

platform="${1:-}"
case "$platform" in
  android | ios | web) ;;
  *)
    echo "Usage: $0 <android|ios|web>"
    exit 1
    ;;
esac

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
tmp_root="${RUNNER_TEMP:-$(mktemp -d)}"
pack_dir="$tmp_root/plugin-package"
test_app="$tmp_root/plugin-example-app"
skip_package_build="${CAPGO_VERIFY_PACKED_SKIP_BUILD:-0}"

cd "$repo_root"

if [[ "$skip_package_build" != "1" ]]; then
  bun run build
fi

rm -rf "$pack_dir" "$test_app"
mkdir -p "$pack_dir" "$test_app"
bun pm pack --destination "$pack_dir" --quiet

shopt -s nullglob
packed_packages=("$pack_dir"/*.tgz)
shopt -u nullglob
if [[ "${#packed_packages[@]}" -ne 1 ]]; then
  echo "Expected exactly one package tarball, found ${#packed_packages[@]}"
  exit 1
fi

plugin_name="$(bun -e 'console.log(require("./package.json").name)')"
cp -R example-app/. "$test_app/"
cd "$test_app"
bun remove "$plugin_name"
bun add "${packed_packages[0]}"
CAPGO_USE_PACKED_PLUGIN=1 bun run build

plugin_path="$(node -p "require('path').dirname(require.resolve('@capgo/cordova-updater/package.json'))")"
plugin_spec="file:${plugin_path}"
# Cordova platform add resolves plugin sources from package.json. Rewrite the packed
# tarball dependency to the installed node_modules path so npm view is not called on .tgz.
node -e "
const fs = require('fs');
const [pluginName, pluginSpec] = process.argv.slice(1);
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
pkg.devDependencies[pluginName] = pluginSpec;
fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\n');
" "$plugin_name" "$plugin_spec"
# Use %ENV so Perl does not treat @capgo in scoped package paths as an array.
PLUGIN_PATH="$plugin_path" perl -pi -e 's|spec="\.\."|spec="$ENV{PLUGIN_PATH}"|' config.xml

case "$platform" in
  android)
    if [[ ! -d platforms/android ]]; then
      bunx cordova platform add android
    fi
    bunx cordova prepare android
    bunx cordova build android --no-interactive
    ;;
  ios)
    if [[ ! -d platforms/ios ]]; then
      bunx cordova platform add ios
    fi
    bunx cordova prepare ios

    ios_root="platforms/ios"
    deployment_target="$(
      node -e "
      const fs = require('fs');
      const c = fs.readFileSync('config.xml', 'utf8');
      const m =
        c.match(/<preference[^>]*name=[\"']deployment-target[\"'][^>]*value=[\"']([^\"']+)[\"']/i) ||
        c.match(/<preference[^>]*value=[\"']([^\"']+)[\"'][^>]*name=[\"']deployment-target[\"']/i);
      console.log(m ? m[1] : '13.0');
      "
    )"

    # cordova-ios 8+ no longer creates a Podfile when plugins declare no CocoaPods
    # dependencies, but pod install still needs that file to materialize the workspace.
    # Match the template Apache Cordova writes for CocoaPods backed plugins.
    if [[ ! -f "$ios_root/Podfile" ]]; then
      cat > "$ios_root/Podfile" <<EOF
# DO NOT MODIFY -- auto-generated by Apache Cordova
platform :ios, '${deployment_target}'

target 'App' do
	project 'App.xcodeproj'
end
EOF
    fi

    (cd "$ios_root" && pod install --repo-update)

    # Use Cordova's compile path so CocoaPods script phases resolve Podfile.lock paths
    # the same way as normal ios builds (raw xcodebuild hits a bad relative path on ios 8).
    bunx cordova compile ios --debug --no-interactive -- \
      -destination "generic/platform=iOS Simulator" \
      CODE_SIGNING_ALLOWED=NO \
      SWIFT_VERSION=5.0 \
      "IPHONEOS_DEPLOYMENT_TARGET=${deployment_target}"
    ;;
  web)
    ;;
esac
